package dev.xclipse.gpulab;
import java.util.*;
import java.util.regex.*;
final class ArchitectureLab {
 static final Pattern INST=Pattern.compile("^\\s*((?:s_|v_|ds_|buffer_|global_|flat_|image_|scratch_|tbuffer_|exp_)[a-z0-9_]+)\\s*(.*?)\\s*(?://|;)\\s*[0-9A-Fa-f]+:\\s*((?:[0-9A-Fa-f]{8}\\s*)+)$");
 static final Pattern REG=Pattern.compile("^\\s*(sgpr_count|vgpr_count|wave_size)\\((\\d+)\\)");
 static final Pattern WMMA=Pattern.compile("\\bv_(?:wmma|mfma)_[a-z0-9_]+\\b");
 static String norm(String a){return a.trim().replaceAll("\\s+"," ").replaceAll("\\s*,\\s*",",").replaceAll("\\blit\\((0x[0-9a-fA-F]+)\\)","$1");}
 static String category(String a){String op=a.split("\\s+",2)[0];if(op.startsWith("v_wmma")||op.startsWith("v_mfma"))return "Matrix";if(op.startsWith("v_pk_")||op.startsWith("v_dot")||op.contains("_mix"))return "Packed / mixed precision";if(op.startsWith("s_load")||op.startsWith("s_store"))return "Scalar memory";if(op.startsWith("s_"))return "Scalar / control";if(op.startsWith("v_"))return "Vector ALU";if(op.startsWith("ds_"))return "LDS";return "Memory / export";}
 static final class Sample {String wave,asm,words;Sample(String w,String a,String x){wave=w;asm=a;words=x.trim().toUpperCase(Locale.ROOT).replaceAll("\\s+"," ");}String key(){return wave+"|"+norm(asm);}String full(){return key()+"|"+words;}}
 static List<Sample> samples(String report){LinkedHashMap<String,Sample> set=new LinkedHashMap<>();String wave="?";for(String line:report.split("\n")){String t=line.trim();if(t.startsWith("[TEST]")||t.startsWith("asic("))wave="?";Matcher reg=REG.matcher(t);if(reg.find()&&reg.group(1).equals("wave_size"))wave=reg.group(2);Matcher m=INST.matcher(t);if(m.matches()&&!m.group(1).equals("s_code_end")){Sample x=new Sample(wave,m.group(1)+(m.group(2).isEmpty()?"":" "+m.group(2)),m.group(3));set.putIfAbsent(x.full(),x);}}return new ArrayList<>(set.values());}
 static List<Sample> seed(String text){List<Sample> a=new ArrayList<>();for(String l:text.split("\n")){if(l.startsWith("#"))continue;int i=l.indexOf('|'),j=l.lastIndexOf('|');if(i>0&&j>i)a.add(new Sample(l.substring(0,i),l.substring(i+1,j),l.substring(j+1)));}return a;}
 static String database(String seed,String report){LinkedHashMap<String,Sample> all=new LinkedHashMap<>();for(Sample x:seed(seed))all.put(x.full(),x);if(report.contains("asic(MGFX2)"))for(Sample x:samples(report))all.put(x.full(),x);Set<String> ops=new TreeSet<>();Map<String,List<Sample>> categories=new TreeMap<>();for(Sample x:all.values()){ops.add(x.asm.split("\\s+",2)[0]);categories.computeIfAbsent(category(x.asm),k->new ArrayList<>()).add(x);}
  StringBuilder s=new StringBuilder("[MGFX2 observed instruction database]\nDistinct mnemonics="+ops.size()+" unique wave/assembly/words="+all.size()+"\nSeed capture and current disassembly when tagged MGFX2; not an exhaustive silicon ISA.\n");
  for(Map.Entry<String,List<Sample>> e:categories.entrySet()){s.append("\n[").append(e.getKey()).append("] samples=").append(e.getValue().size()).append('\n');for(Sample x:e.getValue())s.append("wave").append(x.wave).append(" | ").append(x.asm).append(" | ").append(x.words).append('\n');}
  return s.toString();}
 static String reference(String seed,String report,String ref){Map<String,Sample> observed=new LinkedHashMap<>();for(Sample x:seed(seed))observed.put(x.full(),x);if(report.contains("asic(MGFX2)"))for(Sample x:samples(report))observed.put(x.full(),x);Map<String,Set<String>> enc=new HashMap<>();StringBuilder s=new StringBuilder("[MGFX2 vs GFX1100 / LLVM offline assembly]\n");int same=0,diff=0,missing=0,available=0;
  for(String line:ref.split("\n")){if(line.startsWith("#")){s.append(line).append('\n');continue;}String[] p=line.split("\t",-1);if(p.length<6)continue;if(p[4].equals("ASSEMBLED")){available++;enc.computeIfAbsent(p[0]+"|"+norm(p[1]),k->new TreeSet<>()).add(p[3]);}}
  for(Sample x:observed.values()){Set<String> r=enc.get(x.key());String status;if(r==null){status="NO MATCHING REFERENCE / UNASSEMBLED";missing++;}else if(r.contains(x.words)){status="EXACT WORD MATCH";same++;}else{status="ENCODING DIFFERENCE CANDIDATE";diff++;}s.append(status).append(" | wave").append(x.wave).append(" | ").append(x.asm).append("\n MGFX2 ").append(x.words).append("\n GFX1100 ").append(r==null?"—":r).append('\n');}
  s.append("\nSUMMARY exact=").append(same).append(" difference candidates=").append(diff).append(" no reference=").append(missing).append(" assembled reference rows=").append(available).append('\n');if(available==0)s.append("Reference asset missing or empty; generate with tools/generate_isa_reference.py.\n");
  return s.append("Comparison uses same mnemonic, operands and wave where available. LLVM may select a different valid encoding form; a mismatch is not proof of opcode incompatibility. Unassembled Samsung syntax is not proof of absent GFX11 instruction.\n").toString();}
 static String registers(String report){StringBuilder s=new StringBuilder("[SGPR / VGPR / Wave comparison]\n");String test="",sg="?",vg="?",wave="?";Set<String> rows=new LinkedHashSet<>();for(String l:report.split("\n")){String t=l.trim();if(t.startsWith("[TEST]")){test=t.substring(6).split("\\|",2)[0].trim();sg=vg=wave="?";}Matcher m=REG.matcher(t);if(m.find()){switch(m.group(1)){case "sgpr_count":sg=m.group(2);break;case "vgpr_count":vg=m.group(2);break;case "wave_size":wave=m.group(2);rows.add(test+" | wave="+wave+" SGPR="+sg+" VGPR="+vg);break;}}if(t.startsWith("AMD statistics")||t.startsWith("Executable ")||t.startsWith("PASS mismatch")||t.startsWith("FAIL mismatch"))rows.add(test+" | "+t);}
  for(String row:rows)s.append(row).append('\n');if(rows.isEmpty())s.append("No shader metadata in capture.\n");
  Map<String,Set<String>> waves=new TreeMap<>();for(Sample x:samples(report))waves.computeIfAbsent(x.wave,k->new TreeSet<>()).add(x.asm.split("\\s+",2)[0]);Set<String> a=waves.getOrDefault("32",Collections.emptySet()),b=waves.getOrDefault("64",Collections.emptySet());Set<String> aa=new TreeSet<>(a),bb=new TreeSet<>(b);aa.removeAll(b);bb.removeAll(a);s.append("\nWave32 unique mnemonic count=").append(a.size()).append(" Wave64=").append(b.size()).append("\nOnly observed wave32=").append(aa).append("\nOnly observed wave64=").append(bb).append("\nUse paired shaders with the same inputs. Register allocation is compiler-reported, not physical occupancy. KHR subgroup metadata can disagree with disassembly; retain both.\n");return s.toString();}
 static String matrix(String report,String vk,String ref){StringBuilder s=new StringBuilder("[WMMA evidence / variants]\n");Set<String> observed=new TreeSet<>();for(Sample x:samples(report))if(WMMA.matcher(x.asm).find())observed.add(x.asm+" | "+x.words);s.append("Observed matrix mnemonics in current driver disassembly: ").append(observed).append('\n');
  for(String line:ref.split("\n")){String[] p=line.split("\t",-1);if(p.length>=6&&p[1].startsWith("v_wmma"))s.append("GFX1100 reference wave").append(p[0]).append(" | ").append(p[1]).append(" | ").append(p[4]).append(" | ").append(p[3]).append('\n');}
  boolean advertised=Research.extensions(vk).contains("VK_KHR_cooperative_matrix");s.append("Current driver advertises cooperative matrix: ").append(advertised).append('\n');boolean matrixTest=false;for(String l:report.split("\n")){if(l.startsWith("[TEST]")){matrixTest=l.toLowerCase(Locale.ROOT).contains("matrix")||l.toLowerCase(Locale.ROOT).contains("wmma");if(matrixTest)s.append(l).append('\n');}else if(matrixTest&&(l.startsWith("PASS mismatch")||l.startsWith("FAIL mismatch")||l.startsWith("INCONCLUSIVE")))s.append(l).append('\n');}
  if(observed.isEmpty())s.append("No WMMA mnemonic observed; hardware remains undetermined.\n");else s.append("Driver emitted matrix mnemonic(s); correlate with PASS and exact shader to establish functional evidence.\n");
  return s.append("Hypotheses: compiler lowering to ALU/subgroup; alternate mobile encoding or operand layout; firmware/feature gating; physical omission. None is proven by an absent extension, failed test or strings. LLVM reference assembly never executes on the device. RADV mesh/ray and matrix fallback are user-reported, not native WMMA proof.\n").toString();}
}
